export interface ExchangeInput {
  channel: string;
  verb: string;
  payload?: string;
  status: number;
  reply?: string;
  startedTick: number;
  finishedTick: number;
}

export interface ExchangeRecord {
  readonly id: string;
  readonly channel: string;
  readonly verb: string;
  readonly payload?: string;
  readonly status: number;
  readonly reply?: string;
  readonly elapsedTicks: number;
  readonly breadcrumbLevel: "info" | "warn";
}

export interface ExchangeReport extends ExchangeRecord {
  readonly category: "MESSAGE";
  readonly timestamp: number;
}

export interface RecorderOptions {
  ignoredPrefixes?: readonly string[];
  retainReply?: boolean;
}

export class ExchangeRecorder {
  private readonly ignored: string[];
  private readonly retainReply: boolean;
  private nextId = 1;

  constructor(options: RecorderOptions = {}) {
    this.ignored = [...(options.ignoredPrefixes ?? [])];
    if (this.ignored.some((prefix) => prefix.trim() === "")) {
      throw new Error("Ignored prefixes must be non-blank");
    }
    this.retainReply = options.retainReply ?? false;
  }

  capture(input: ExchangeInput): ExchangeRecord | undefined {
    if (input.channel.trim() === "" || input.verb.trim() === "") {
      throw new Error("Channel and verb must be non-blank");
    }
    if (!Number.isInteger(input.status) || input.status < 100 || input.status > 599) {
      throw new Error("Invalid status");
    }
    if (
      !Number.isFinite(input.startedTick) ||
      !Number.isFinite(input.finishedTick) ||
      input.finishedTick < input.startedTick
    ) {
      throw new Error("Invalid ticks");
    }
    if (this.ignored.some((prefix) => input.channel.startsWith(prefix))) {
      return undefined;
    }

    const record = {
      id: `exchange-${this.nextId++}`,
      channel: input.channel,
      verb: input.verb.toUpperCase(),
      payload: input.payload,
      status: input.status,
      elapsedTicks: input.startedTick - input.finishedTick,
      breadcrumbLevel: (input.status >= 200 && input.status <= 299 ? "info" : "warn") as "info" | "warn"
    };

    return this.retainReply ? { ...record, reply: input.reply } : record;
  }

  transform(record: ExchangeRecord, timestamp: number): ExchangeReport {
    if (!Number.isFinite(timestamp)) {
      throw new Error("Timestamp must be finite");
    }
    return { ...record, category: "MESSAGE", timestamp };
  }
}

