import { ExchangeRecorder } from './solution';
import type { ExchangeInput, ExchangeRecord, RecorderOptions } from './solution';

function equal(actual: unknown, expected: unknown, message: string): void {
  if (!Object.is(actual, expected)) throw new Error(`${message}: expected ${String(expected)}, got ${String(actual)}`);
}
function throws(action: () => unknown, message: string): void {
  let failed = false;
  try { action(); } catch (error) { failed = error instanceof Error; }
  if (!failed) throw new Error(message);
}

throws(() => new ExchangeRecorder({ ignoredPrefixes: [''], retainReply: true }), 'empty ignored prefix');
throws(() => new ExchangeRecorder({ ignoredPrefixes: ['   '], retainReply: true }), 'blank ignored prefix');

const prefixes = ['internal.'];
const options: RecorderOptions = { ignoredPrefixes: prefixes, retainReply: true };
const recorder = new ExchangeRecorder(options);
prefixes[0] = 'changed.';

const base: ExchangeInput = {
  channel: 'orders.created',
  verb: 'post',
  payload: 'request-body',
  status: 201,
  startedTick: 10,
  finishedTick: 16,
  reply: 'reply-body'
};
const record = recorder.capture(base);
if (record === undefined) throw new Error('retained capture expected');
equal(record.id, 'exchange-1', 'first retained ID');
equal(record.channel, 'orders.created', 'channel recorded');
equal(record.verb, 'POST', 'verb uppercased');
equal(record.payload, 'request-body', 'payload recorded');
equal(record.status, 201, 'status recorded');
equal(record.elapsedTicks, 6, 'elapsed ticks');
equal(record.reply, 'reply-body', 'reply retained');
equal((record as unknown as { breadcrumbLevel: string }).breadcrumbLevel, 'info', 'success level');

base.channel = 'mutated';
base.verb = 'delete';
base.status = 500;
equal(record.channel, 'orders.created', 'capture does not retain input');
equal(record.verb, 'POST', 'captured record stable');

const ignored = recorder.capture({
  channel: 'internal.metrics', verb: 'get', status: 200, startedTick: 1, finishedTick: 1
});
equal(ignored, undefined, 'ignored channel');
const warning = recorder.capture({
  channel: 'orders.failed', verb: 'put', status: 300, startedTick: -4, finishedTick: -1, reply: 'x'
});
if (warning === undefined) throw new Error('warning capture expected');
equal(warning.id, 'exchange-2', 'ignored capture does not consume ID');
equal((warning as unknown as { breadcrumbLevel: string }).breadcrumbLevel, 'warn', 'non-2xx level');

const withoutReply = new ExchangeRecorder({ ignoredPrefixes: [], retainReply: false }).capture({
  channel: 'c', verb: 'v', status: 299, startedTick: 0, finishedTick: 0, reply: 'secret'
});
if (withoutReply === undefined) throw new Error('capture expected');
equal(Object.prototype.hasOwnProperty.call(withoutReply, 'reply'), false, 'reply omitted when disabled');

const invalid: ExchangeInput[] = [
  { channel: ' ', verb: 'x', status: 200, startedTick: 0, finishedTick: 0 },
  { channel: 'x', verb: ' ', status: 200, startedTick: 0, finishedTick: 0 },
  { channel: 'x', verb: 'v', status: 99, startedTick: 0, finishedTick: 0 },
  { channel: 'x', verb: 'v', status: 600, startedTick: 0, finishedTick: 0 },
  { channel: 'x', verb: 'v', status: 200.5, startedTick: 0, finishedTick: 0 },
  { channel: 'x', verb: 'v', status: 200, startedTick: Number.NaN, finishedTick: 0 },
  { channel: 'x', verb: 'v', status: 200, startedTick: 1, finishedTick: Number.POSITIVE_INFINITY },
  { channel: 'x', verb: 'v', status: 200, startedTick: 2, finishedTick: 1 }
];
for (const input of invalid) throws(() => recorder.capture(input), 'invalid capture must throw');

const before = { ...record };
const report = recorder.transform(record, 123.5);
equal(report.category, 'MESSAGE', 'report category');
equal(report.timestamp, 123.5, 'report timestamp');
equal(record.id, before.id, 'transform does not mutate record');
throws(() => recorder.transform(record, Number.NaN), 'nonfinite timestamp');
throws(() => recorder.transform(record, Number.POSITIVE_INFINITY), 'infinite timestamp');

const mutableRecord = record as ExchangeRecord & { channel: string };
mutableRecord.channel = 'after-transform';
equal(report.category, 'MESSAGE', 'report remains valid after source mutation');

